const fs = require('fs');
const input = fs.readFileSync(0, 'utf8');
const parts = input.trim().split(/\s+/).map(Number);

if (parts.length > 0) {
    const n = parts[0];
    const arr = parts.slice(1, n + 1).sort((a, b) => a - b);
    const target = parts[n + 1];

    let low = 0, high = arr.length - 1, found = -1;
    while (low <= high) {
        let mid = Math.floor((low + high) / 2);
        if (arr[mid] === target) {
            found = mid;
            break;
        } else if (arr[mid] < target) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    console.log(found >= 0 ? "Found at " + found : "Not Found");
}
